insert into public.locations (id, slug, name, city, description, image_url, latitude, longitude) values
  ('6f1d1c4e-0001-4a5b-9c1d-000000000001', 'ouaga-2000', 'Ouaga 2000', 'Ouagadougou', 'Quartier résidentiel haut de gamme au sud de la capitale, proche des institutions et des grands axes.', '/images/zones/ouaga-2000.webp', 12.3155, -1.4915),
  ('6f1d1c4e-0001-4a5b-9c1d-000000000002', 'saaba', 'Saaba', 'Ouagadougou', 'Commune en pleine expansion à l’est de Ouagadougou, idéale pour une première acquisition.', '/images/zones/saaba.webp', 12.3765, -1.4235),
  ('6f1d1c4e-0001-4a5b-9c1d-000000000003', 'komsilga', 'Komsilga', 'Ouagadougou', 'Zone calme au sud-ouest, appréciée pour ses grandes parcelles et ses prix accessibles.', '/images/zones/komsilga.webp', 12.2455, -1.5465),
  ('6f1d1c4e-0001-4a5b-9c1d-000000000004', 'dassasgho', 'Dassasgho', 'Ouagadougou', 'Quartier central et animé de l’est de la capitale, où se trouve notre bureau.', '/images/zones/dassasgho.webp', 12.3762, -1.4825),
  ('6f1d1c4e-0001-4a5b-9c1d-000000000005', 'pabre', 'Pabré', 'Ouagadougou', 'Commune verdoyante au nord, prisée pour les projets agricoles et les résidences secondaires.', '/images/zones/pabre.webp', 12.5215, -1.5785),
  ('6f1d1c4e-0001-4a5b-9c1d-000000000006', 'tenkodogo', 'Tenkodogo', 'Tenkodogo', 'Chef-lieu du Centre-Est, ville dynamique au fort potentiel de développement.', '/images/zones/tenkodogo.webp', 11.7801, -0.3697);
insert into public.properties (id, slug, reference, title, description, location_id, city, district, address, latitude, longitude, price, surface, type, status, payment_options, installment_months, legal_status, road_access, has_water, has_electricity, distance_to_paved_road_m, topography, nearby, amenities, cadastral_plan_url, is_featured, is_published, views_count, created_at) values
  ('13bbeb1c-b7c3-43d5-9c67-09bea600ff8d', 'terrain-residentiel-ouaga-2000-500-m2', 'PH-OUA-001', 'Terrain résidentiel de 500 m² à Ouaga 2000', 'Belle parcelle d’angle dans l’extension sud de Ouaga 2000, au cœur d’un quartier résidentiel recherché. Bordée par une voie bitumée, elle est déjà raccordable à l’eau (ONEA) et à l’électricité (SONABEL). Idéale pour une villa familiale avec jardin ou un petit immeuble résidentiel.', '6f1d1c4e-0001-4a5b-9c1d-000000000001', 'Ouagadougou', 'Ouaga 2000 (extension sud)', null, 12.3121, -1.4878, 18500000, 500, 'residentiel', 'disponible', array['comptant', 'echelonne']::payment_option[], 12, 'acd', 'Voie bitumée en façade', true, true, 0, 'Terrain plat, sol latéritique stable', '[{"type":"ecole","name":"Complexe scolaire international","distance_m":650},{"type":"commerce","name":"Supermarché et pharmacie","distance_m":900},{"type":"route","name":"Boulevard Mouammar Kadhafi","distance_m":1200}]'::jsonb, array['Parcelle d’angle', 'Quartier sécurisé', 'Voisinage résidentiel']::text[], '/images/terrains/t01-3.webp', true, true, 0, '2026-09-28T09:00:00.000Z'),
  ('a2bfeada-3e08-4dad-aa45-96469c6d033f', 'parcelle-saaba-300-m2-wend-panga', 'PH-OUA-002', 'Parcelle de 300 m² à Saaba — Cité Wend-Panga', 'Parcelle de 300 m² dans la cité Wend-Panga à Saaba, zone lotie en plein développement. Accès facile depuis la RN4, école à proximité immédiate. Une excellente opportunité pour une première acquisition, avec un paiement échelonné jusqu’à 18 mois.', '6f1d1c4e-0001-4a5b-9c1d-000000000002', 'Ouagadougou', 'Saaba, secteur 3', null, 12.3791, -1.4192, 3500000, 300, 'residentiel', 'disponible', array['comptant', 'echelonne']::payment_option[], 18, 'attestation_attribution', 'Voie latéritique carrossable', true, true, 450, 'Terrain plat', '[{"type":"ecole","name":"École primaire publique","distance_m":300},{"type":"commerce","name":"Marché de Saaba","distance_m":1500},{"type":"route","name":"Route nationale 4","distance_m":450}]'::jsonb, array['Zone lotie', 'Bornage effectué', 'Proche des commodités']::text[], '/images/terrains/t02-3.webp', true, true, 0, '2026-09-25T09:00:00.000Z'),
  ('d2b48100-882a-4e84-b6f2-549f279ee400', 'terrain-komsilga-400-m2-jardins', 'PH-OUA-003', 'Terrain de 400 m² — Les Jardins de Komsilga', 'Grande parcelle de 400 m² dans un environnement calme et verdoyant, à quelques minutes de la route de Léo. Les voies sont tracées et l’électricité arrive en bordure de site. Idéale pour une maison familiale avec jardin.', '6f1d1c4e-0001-4a5b-9c1d-000000000003', 'Ouagadougou', 'Komsilga, Les Jardins', null, 12.2489, -1.5512, 4200000, 400, 'residentiel', 'disponible', array['comptant', 'echelonne']::payment_option[], 24, 'attestation_attribution', 'Voies tracées et latéritées', false, true, 1200, 'Légère pente, bon drainage naturel', '[{"type":"ecole","name":"CEG de Komsilga","distance_m":1100},{"type":"sante","name":"CSPS","distance_m":1400},{"type":"route","name":"Route de Léo","distance_m":1200}]'::jsonb, array['Environnement calme', 'Arbres existants', 'Grand voisinage vert']::text[], '/images/terrains/t03-3.webp', true, true, 0, '2026-09-21T09:00:00.000Z'),
  ('0609f11d-6ca3-4125-a298-0e3ef6dc4755', 'parcelle-commerciale-dassasgho-600-m2', 'PH-OUA-004', 'Parcelle commerciale de 600 m² à Dassasgho', 'Parcelle commerciale avec titre foncier, située sur un axe très passant de Dassasgho. Sa façade sur voie bitumée offre une excellente visibilité pour un commerce, une agence, des bureaux ou un immeuble à usage mixte.', '6f1d1c4e-0001-4a5b-9c1d-000000000004', 'Ouagadougou', 'Dassasgho, axe principal', null, 12.3741, -1.4803, 32000000, 600, 'commercial', 'disponible', array['comptant']::payment_option[], null, 'titre_foncier', 'Façade sur voie bitumée très passante', true, true, 0, 'Terrain plat, viabilisé', '[{"type":"commerce","name":"Marché de Dassasgho","distance_m":400},{"type":"transport","name":"Arrêt de bus SOTRACO","distance_m":150},{"type":"sante","name":"Clinique privée","distance_m":700}]'::jsonb, array['Forte visibilité', 'Idéal commerce ou bureaux', 'Titre foncier']::text[], '/images/terrains/t04-3.webp', true, true, 0, '2026-09-29T09:00:00.000Z'),
  ('4e644b39-61a5-4222-b1d9-b1a8dee8beea', 'domaine-agricole-pabre-1-hectare', 'PH-OUA-005', 'Domaine agricole d’un hectare à Pabré', 'Domaine d’un hectare à Pabré, au sol fertile et doté d’un puits. Parfait pour un projet de maraîchage, de verger ou d’élevage, à moins de 40 minutes du centre de Ouagadougou.', '6f1d1c4e-0001-4a5b-9c1d-000000000005', 'Ouagadougou', 'Pabré, route de Kongoussi', null, 12.5291, -1.5873, 12000000, 10000, 'agricole', 'disponible', array['comptant', 'echelonne']::payment_option[], 12, 'attestation_attribution', 'Piste rurale praticable toute l’année', true, false, 2500, 'Terrain plat, sol fertile, forage possible', '[{"type":"route","name":"Route de Kongoussi","distance_m":2500},{"type":"commerce","name":"Marché de Pabré","distance_m":3000}]'::jsonb, array['Sol fertile', 'Puits existant', 'Idéal maraîchage ou verger']::text[], '/images/terrains/t05-3.webp', false, true, 0, '2026-09-10T09:00:00.000Z'),
  ('76128729-7bcf-4acd-b29c-a3ef8b140681', 'parcelle-tenkodogo-300-m2-secteur-5', 'PH-TKD-006', 'Parcelle de 300 m² à Tenkodogo — secteur 5', 'Parcelle de 300 m² dans le secteur 5 de Tenkodogo, quartier résidentiel en développement proche du lycée provincial et du grand marché. Eau et électricité disponibles dans la rue.', '6f1d1c4e-0001-4a5b-9c1d-000000000006', 'Tenkodogo', 'Tenkodogo, secteur 5', null, 11.7843, -0.3648, 2300000, 300, 'residentiel', 'disponible', array['comptant', 'echelonne']::payment_option[], 12, 'attestation_attribution', 'Voie latéritique', true, true, 600, 'Terrain plat', '[{"type":"commerce","name":"Grand marché de Tenkodogo","distance_m":1300},{"type":"ecole","name":"Lycée provincial","distance_m":900},{"type":"route","name":"Route nationale 16","distance_m":600}]'::jsonb, array['Prix accessible', 'Quartier en développement']::text[], '/images/terrains/t06-3.webp', true, true, 0, '2026-09-23T09:00:00.000Z'),
  ('bb517af5-777e-44a5-8171-edf66fb165bc', 'terrain-tenkodogo-500-m2-zoungrana', 'PH-TKD-007', 'Terrain de 500 m² — Domaine Zoungrana, Tenkodogo', 'Grande parcelle de 500 m² avec ACD, dans un quartier résidentiel calme de Tenkodogo, à 100 m d’une voie bitumée. Actuellement réservée : contactez-nous pour être informé si elle redevient disponible.', '6f1d1c4e-0001-4a5b-9c1d-000000000006', 'Tenkodogo', 'Tenkodogo, secteur 3', null, 11.7768, -0.3751, 4800000, 500, 'residentiel', 'reserve', array['comptant', 'echelonne']::payment_option[], 12, 'acd', 'Voie bitumée à 100 m', true, true, 100, 'Terrain plat', '[{"type":"sante","name":"Centre hospitalier régional","distance_m":1500},{"type":"ecole","name":"École privée","distance_m":500}]'::jsonb, array['Idéal villa', 'Quartier résidentiel calme']::text[], '/images/terrains/t07-3.webp', false, true, 0, '2026-09-01T09:00:00.000Z'),
  ('c61e5796-d289-4c09-8692-cb5331c1635f', 'parcelle-saaba-250-m2-premiere-acquisition', 'PH-OUA-008', 'Parcelle de 250 m² à Saaba — idéale première acquisition', 'Parcelle de 250 m² à Saaba, accessible avec un paiement échelonné jusqu’à 24 mois. Parfaite pour construire progressivement votre maison.', '6f1d1c4e-0001-4a5b-9c1d-000000000002', 'Ouagadougou', 'Saaba, secteur 6', null, 12.3712, -1.4124, 2700000, 250, 'residentiel', 'disponible', array['echelonne']::payment_option[], 24, 'attestation_attribution', 'Voie latéritique', false, true, 900, 'Terrain plat', '[{"type":"ecole","name":"École primaire","distance_m":600},{"type":"lieu_culte","name":"Église et mosquée","distance_m":400}]'::jsonb, array['Mensualités accessibles', 'Bornage effectué']::text[], '/images/terrains/t08-3.webp', true, true, 0, '2026-09-17T09:00:00.000Z'),
  ('ce777a28-96a1-440f-bfa6-30bad3f8a531', 'terrain-mixte-ouaga-2000-800-m2', 'PH-OUA-009', 'Terrain mixte de 800 m² à Ouaga 2000', 'Terrain à double façade bitumée, adapté à un projet résidentiel et commercial. Ce terrain a été vendu ; d’autres opportunités similaires sont disponibles sur demande.', '6f1d1c4e-0001-4a5b-9c1d-000000000001', 'Ouagadougou', 'Ouaga 2000, zone mixte', null, 12.3189, -1.4987, 36000000, 800, 'mixte', 'vendu', array['comptant']::payment_option[], null, 'titre_foncier', 'Double façade bitumée', true, true, 0, 'Terrain plat, viabilisé', '[{"type":"commerce","name":"Centre commercial","distance_m":500},{"type":"route","name":"Échangeur de Ouaga 2000","distance_m":1500}]'::jsonb, array['Double façade', 'Usage résidentiel et commercial']::text[], '/images/terrains/t09-3.webp', false, true, 0, '2026-08-02T09:00:00.000Z'),
  ('e4b55029-df4e-4c15-a92a-13de318ffc28', 'terrain-komsilga-2-hectares-agricole', 'PH-OUA-010', 'Terrain agricole de 2 hectares à Komsilga', 'Deux hectares à Komsilga pour un projet agricole, une ferme avicole ou un investissement foncier de long terme.', '6f1d1c4e-0001-4a5b-9c1d-000000000003', 'Ouagadougou', 'Komsilga, zone rurale', null, 12.2271, -1.5689, 18000000, 20000, 'agricole', 'disponible', array['comptant', 'echelonne']::payment_option[], 18, 'attestation_attribution', 'Piste rurale', false, false, 3500, 'Terrain légèrement vallonné', '[{"type":"route","name":"Route de Léo","distance_m":3500}]'::jsonb, array['Grande superficie', 'Projet agricole ou ferme']::text[], '/images/terrains/t10-3.webp', false, true, 0, '2026-08-22T09:00:00.000Z'),
  ('9f1c00a4-52c4-4be9-8798-0cb7bd06dba0', 'parcelle-industrielle-saaba-2000-m2', 'PH-OUA-011', 'Parcelle industrielle de 2 000 m² à Saaba', 'Parcelle de 2 000 m² en zone d’activités, accessible aux poids lourds et proche de la RN4. Adaptée à un entrepôt, un atelier ou une unité de transformation.', '6f1d1c4e-0001-4a5b-9c1d-000000000002', 'Ouagadougou', 'Saaba, zone d’activités', null, 12.3654, -1.4302, 22000000, 2000, 'industriel', 'reserve', array['comptant']::payment_option[], null, 'acd', 'Accès poids lourds', true, true, 300, 'Terrain plat, remblayé', '[{"type":"route","name":"Route nationale 4","distance_m":300}]'::jsonb, array['Accès poids lourds', 'Triphasé disponible']::text[], '/images/terrains/t11-3.webp', false, true, 0, '2026-09-06T09:00:00.000Z'),
  ('6ce4ddcb-db07-47f2-9850-717f8edb548a', 'parcelle-dassasgho-300-m2-centre', 'PH-OUA-012', 'Parcelle de 300 m² au centre de Dassasgho', 'Parcelle de 300 m² au cœur de Dassasgho, à proximité de toutes les commodités. Ce terrain a été vendu.', '6f1d1c4e-0001-4a5b-9c1d-000000000004', 'Ouagadougou', 'Dassasgho, secteur 28', null, 12.3803, -1.4851, 9500000, 300, 'residentiel', 'vendu', array['comptant', 'echelonne']::payment_option[], 6, 'acd', 'Voie latéritique, bitume à 200 m', true, true, 200, 'Terrain plat', '[{"type":"ecole","name":"Lycée de Dassasgho","distance_m":500},{"type":"commerce","name":"Marché de Dassasgho","distance_m":800}]'::jsonb, array['Quartier central', 'Toutes commodités']::text[], '/images/terrains/t12-3.webp', false, true, 0, '2026-07-18T09:00:00.000Z');
