insert into public.faq (question, answer, position, is_published) values
  ('Comment acheter un terrain chez Progrès Habitat ?', 'Choisissez un terrain sur le site ou contactez un conseiller, puis nous organisons une visite gratuite. Après vérification des documents, vous réservez avec un acompte et signez le contrat. Le solde est réglé comptant ou en plusieurs fois, et nous vous remettons les documents officiels.', 1, true),
  ('Quels documents sont fournis ?', 'Selon le terrain : attestation d''attribution, Arrêté de Cession Définitive (ACD) ou titre foncier, accompagnés du plan de situation et du procès-verbal de bornage. Le document disponible est indiqué sur chaque fiche.', 2, true),
  ('Peut-on payer en plusieurs fois ?', 'Oui, la plupart de nos terrains sont proposés avec un paiement échelonné. Après un acompte, le solde est réparti en mensualités (durée indiquée sur chaque fiche). Les paiements se font par Orange Money, Moov Money, virement ou en agence, contre reçu.', 3, true),
  ('Comment réserver une visite ?', 'Cliquez sur « Demander une visite » depuis la fiche d’un terrain, ou contactez-nous par WhatsApp ou téléphone. Nous confirmons le rendez-vous et vous accompagnons sur place. Pour la diaspora, nous proposons des visites en vidéo.', 4, true),
  ('Comment vérifier la propriété d’un terrain ?', 'Nous vous communiquons les références du document (numéro de parcelle, lot, section) afin que vous puissiez les vérifier vous-même auprès des services des domaines ou de la mairie. Vous pouvez aussi vous faire accompagner par un notaire de votre choix.', 5, true),
  ('Quels frais supplémentaires faut-il prévoir ?', 'Selon le statut du terrain, prévoyez les frais de mutation ou de mise à jour du document, les éventuels frais de notaire et les taxes administratives. Nous vous remettons une estimation écrite de ces frais avant toute réservation.', 6, true);
